def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    average_net_loss = (v1 + v2) / 2

    return {
        "value": average_net_loss,
        "trace": {
            "v1": v1,
            "v2": v2,
            "average_net_loss": average_net_loss,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": "monetary"
            }
        }
    }
